<template>
 <div class="talent-overlay" v-back="()=>!busy&&$emit('close')" @click.self="!busy&&$emit('close')">
  <section class="talent-window" role="dialog" aria-modal="true" aria-labelledby="talent-title" ref="dialog" @keydown.tab="trapFocus">
   <header><div class="talent-emblem" aria-hidden="true">✧</div><div><small>MODULE DE PROGRESSION</small><h2 id="talent-title">Arbre de talents</h2></div><div v-if="state.unlocked" class="talent-points"><strong>{{state.available}}</strong><span>/ 41 points<br>disponibles</span></div><button class="talent-close" :disabled="busy" aria-label="Fermer" @click="$emit('close')">×</button></header>
   <template v-if="!state.unlocked">
    <div class="talent-shop"><div class="shop-orbit" aria-hidden="true"><span>⌕</span><span>✦</span><span>ϟ</span><span>↗</span><b>✧</b></div><h3>Quatre voies. Ta propre progression.</h3><p>« Les cristaux ne font pas tout. Ce module t’aidera à tirer le meilleur de tes recherches… à toi de choisir ta voie. »</p><div class="shop-branches"><span v-for="(b,key) in catalog.branches" :key="key" :style="{'--branch':b.color}">{{b.name}}</span></div><div class="shop-price"><strong :class="{missing:state.money<10000000}">10 000 000 ₽</strong><span>+ 30 plaques de chacun des 18 types</span><small>Achat unique · accès permanent · 41 points disponibles dès l’achat</small></div><div class="talent-plates"><span v-for="(label,type) in catalog.types" :key="type" :class="{missing:resource('dark_plate_'+type.toLowerCase())<30}">{{label}} <b>{{resource('dark_plate_'+type.toLowerCase())}} / 30</b></span></div><p class="talent-help">Les talents consomment ensuite leurs propres ressources. Tu peux récupérer gratuitement les points en retirant les talents au bout des chemins ; les ressources ne sont pas remboursées, mais un talent déjà payé peut ensuite être réactivé gratuitement.</p><button class="talent-primary" :disabled="busy||!canPurchase" @click="$emit('command','purchase')">{{busy?'Enregistrement…':'Acquérir le module'}}</button></div>
   </template>
   <template v-else>
    <nav class="talent-branches" aria-label="Spécialisations"><button v-for="(b,key) in catalog.branches" :key="key" :aria-pressed="branch===key" :style="{'--branch':b.color}" @click="focusBranch(key)"><i></i><span>{{b.name}}</span><b>{{state.branches[key]}}<small>/31</small></b></button></nav>
    <div class="talent-layout">
     <div class="talent-map-column">
      <div class="talent-filter"><label v-if="['capture','combat'].includes(branch)">Type <select v-model="type" @change="focusType"><option v-for="(name,t) in catalog.types" :key="t" :value="t">{{name}}</option></select></label><button @click="summary=!summary" :aria-expanded="summary">{{summary?'Masquer les bonus':'Mes bonus'}}</button><button @click="overview">Vue d’ensemble</button></div>
      <div ref="viewport" class="talent-viewport" @wheel.prevent="wheel" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="pointerUp" @pointercancel="pointerCancel">
       <svg class="talent-canvas" :viewBox="`0 0 ${width} ${height}`" aria-label="Arbre circulaire : déplace la carte et sélectionne un talent">
        <defs><radialGradient id="talent-core"><stop stop-color="#c5d4df" stop-opacity=".2"/><stop offset="1" stop-color="#c5d4df" stop-opacity="0"/></radialGradient></defs>
        <g :transform="`translate(${offset.x} ${offset.y}) scale(${zoom})`">
         <talent-tree-graph :state="state" :selected-id="selectedId" :flash-id="flashId" @select="selectNode"/>
        </g>
       </svg>
       <div class="talent-zoom"><button aria-label="Dézoomer" @click="zoomBy(.8)">−</button><span>{{Math.round(zoom*100)}} %</span><button aria-label="Zoomer" @click="zoomBy(1.25)">+</button></div><span class="talent-map-hint">Glisser pour explorer · {{touch?'Pincer':'Molette'}} pour zoomer</span>
       <div v-if="summary" class="talent-summary"><h3>Bonus actifs</h3><p v-if="!state.used">Choisis ton premier chemin.</p><p v-for="line in bonusLines" :key="line">{{line}}</p></div>
      </div>
     </div>
     <aside class="talent-detail" :style="{'--branch':catalog.branches[branch].color}">
      <template v-if="selected"><div class="detail-kicker">{{catalog.branches[selected.branch].name}} <b>{{selected.ultimate?'ULTIME':selected.points+' PT'+(selected.points>1?'S':'')}}</b></div><div class="detail-name"><span>{{glyph(selected)}}</span><h3>{{selected.name}}</h3></div><p>{{selected.description}}</p><p v-if="catalog.branches[selected.branch].description" class="talent-combat-scope" data-talent-combat-scope>{{catalog.branches[selected.branch].description}}</p><span v-if="state.nodes[selected.id]" class="talent-owned">✓ Acquis{{chosenLabel?' · '+chosenLabel:''}}</span>
       <div v-if="selected.choices&&!state.nodes[selected.id]" class="talent-choices"><button v-for="c in selected.choices" :key="c" :aria-pressed="choice===c" @click="choice=c">{{choiceLabels[c]}}<b>{{selected.ultimate?'×2':(c==='offense'?'+':'−')+selected.bonus+' %'}}</b></button></div>
       <div v-if="state.nodes[selected.id]||!alreadyPaid" class="talent-cost"><small>{{state.nodes[selected.id]?'RESSOURCES DÉPENSÉES':'COÛT DU TALENT'}}</small><div v-for="(amount,key) in selected.cost" :key="key" :class="{missing:stock(key)<amount}"><span>{{resourceName(key)}}</span><b>{{format(amount)}} <small>/ {{format(stock(key))}}</small></b></div><div v-if="selected.mixedPlates"><span>Plaques au choix</span><b>{{plateTotal}} / {{selected.mixedPlates}}</b></div></div>
       <div v-else class="talent-cost talent-paid" data-talent-free><small>TALENT DÉJÀ PAYÉ</small><strong>Réactivation gratuite</strong><span>Aucune ressource n’est consommée.</span></div>
       <details v-if="selected.mixedPlates&&!state.nodes[selected.id]&&!alreadyPaid" class="talent-mixed"><summary>Choisir les plaques</summary><button @click="allocatePlates">Répartir depuis mes réserves</button><label v-for="(name,t) in catalog.types" :key="t">{{name}} <small>{{resource('dark_plate_'+t.toLowerCase())}} en sac</small><input type="number" min="0" :max="Math.min(selected.mixedPlates,resource('dark_plate_'+t.toLowerCase()))" :value="plates[t]||0" :aria-label="'Plaques '+name" @input="$set(plates,t,Math.max(0,Math.min(selected.mixedPlates,Number($event.target.value)||0)))"></label></details>
       <p class="talent-requirement">{{state.nodes[selected.id]?refundReason||'Ce talent est au bout du chemin : ses points peuvent être rendus.':available(selected)||(selected.ultimate?'30 points investis · talent ultime accessible.':'Chemin accessible depuis le centre.')}}</p>
       <template v-if="state.nodes[selected.id]"><button v-if="!refundConfirm" class="talent-secondary" :disabled="busy||!!refundReason" @click="refundConfirm=true">Récupérer {{selected.points}} point{{selected.points>1?'s':''}}</button><div v-else class="talent-refund"><p>Tu récupères les points. Ce talent restera payé et pourra être réactivé sans dépenser de ressources.</p><button class="talent-primary" :disabled="busy" @click="command('refund')">Confirmer le retrait</button><button @click="refundConfirm=false">Conserver ce talent</button></div></template>
       <button v-else class="talent-primary" :disabled="busy||!!available(selected)||!affordable||selected.choices&&!choice" @click="command('buy')">{{busy?'Enregistrement…':(alreadyPaid?'Réactiver · ':'Activer · ')+selected.points+' point'+(selected.points>1?'s':'')}}</button><small v-if="!state.nodes[selected.id]&&!affordable" class="missing">Ressources insuffisantes ou plaques à répartir.</small>
       <div class="talent-stepper"><button :disabled="!previous" @click="selectNode(previous)">← Précédent</button><button :disabled="!next" @click="selectNode(next)">Suivant →</button></div>
      </template>
      <template v-else><div class="detail-empty">✧</div><h3>Choisis ta voie</h3><p>Pars du centre et suis les chemins colorés. Sélectionne un talent pour consulter son effet et ses ressources.</p><p>41 points au total, 31 au maximum par spécialisation. Les talents Combat coûtent deux points.</p><button class="talent-secondary" @click="focusType">Explorer cette spécialisation</button><button class="talent-secondary" @click="selectNode(ultimate)">Voir le talent ultime</button></template>
     </aside>
    </div>
   </template>
   <footer v-if="error||notice" aria-live="polite" :class="{error:!!error}">{{error||notice}}</footer>
  </section>
 </div>
</template>
<script>
import catalog from '@/data/talentTree.json';
import TalentTreeGraph from './TalentTreeGraph.vue';
const byId=new Map(catalog.nodes.map(n=>[n.id,n]));
export default{
 name:'TalentTreePanel',components:{TalentTreeGraph},props:{state:Object,busy:Boolean,error:String,notice:String},
 data:()=>({catalog,branch:'capture',type:'Water',selectedId:null,choice:null,plates:{},refundConfirm:false,summary:false,width:700,height:570,zoom:.16,offset:{x:0,y:0},touch:typeof navigator!=='undefined'&&navigator.maxTouchPoints>0,flashId:null,choiceLabels:{offense:'Offense',defense:'Défense',shiny:'Recherche de Shiny',legendary:'Recherche de légendaires'}}),
 computed:{
  selected(){return byId.get(this.selectedId);},alreadyPaid(){return this.state.purchasedNodes?.includes(this.selectedId)||false;},ultimate(){return byId.get(this.branch+'_ultimate');},
  canPurchase(){return this.state.money>=10000000&&Object.keys(catalog.types).every(t=>this.resource('dark_plate_'+t.toLowerCase())>=30);},
  plateTotal(){return Object.values(this.plates).reduce((s,n)=>s+n,0);},
  affordable(){return this.alreadyPaid||this.selected&&Object.entries(this.selected.cost).every(([k,n])=>this.stock(k)>=n)&&(!this.selected.mixedPlates||this.plateTotal===this.selected.mixedPlates&&Object.entries(this.plates).every(([t,n])=>n<=this.resource('dark_plate_'+t.toLowerCase())));},
  refundReason(){if(!this.selected)return null;if(catalog.nodes.some(n=>this.state.nodes[n.id]&&n.parents.includes(this.selected.id)))return 'Retire d’abord les talents qui suivent sur ce chemin.';if(!this.selected.ultimate&&this.state.nodes[this.selected.branch+'_ultimate']&&this.state.branches[this.selected.branch]-this.selected.points<31)return 'Retire d’abord le talent ultime de cette spécialisation.';return null;},
  chosenLabel(){return this.choiceLabels[this.state.nodes[this.selectedId]]||'';},
  previous(){return this.selected?.parents.length?byId.get(this.selected.parents[0]):null;},next(){return catalog.nodes.find(n=>n.parents.includes(this.selectedId));},
  bonusLines(){const b=this.state.bonuses,lines=[];if(b.globalDamage||Object.keys(b.offense).length||Object.keys(b.defense).length)lines.push('Combat : sauvages, raids et Super Combats uniquement.');for(const[t,n]of Object.entries(b.capture))lines.push(`Recherche ${catalog.types[t]} : poids +${n} %`);for(const[t,n]of Object.entries(b.offense))lines.push(`Dégâts ${catalog.types[t]} : +${n} %`);for(const[t,n]of Object.entries(b.defense))lines.push(`Dégâts ${catalog.types[t]} reçus : −${n} %`);for(const [key,label]of Object.entries({globalDamage:'Dégâts globaux',sharedExperience:'XP Multi Exp',globalExperience:'XP globale',globalMoney:'Récompenses en argent'}))if(b[key])lines.push(`${label} : +${b[key]} %`);for(const[source,n]of Object.entries(b.money))if(n)lines.push(`Argent ${ {wild:'sauvages',raid:'raids',tower:'Tour'}[source]} : +${n} %`);if(b.shiny===2)lines.push('Chances de Shiny ×2');if(b.legendary===2)lines.push('Chances de légendaire ×2');return lines;}
 },
 watch:{'state.revision'(){this.refundConfirm=false;}},
 mounted(){this._previousFocus=document.activeElement;this.$nextTick(()=>this.$refs.dialog?.querySelector('button:not(:disabled)')?.focus({preventScroll:true}));this._pointers=new Map();this.$nextTick(()=>{if(!this.$refs.viewport)return;this._resize=new ResizeObserver(()=>{this.measure();if(!this._measured){this._measured=true;this.overview();}});this._resize.observe(this.$refs.viewport);});},
 updated(){if(!this._resize&&this.$refs.viewport){this._resize=new ResizeObserver(()=>this.measure());this._resize.observe(this.$refs.viewport);this.$nextTick(()=>{this.measure();this.overview();});}},
 beforeDestroy(){if(this._previousFocus?.isConnected)this._previousFocus.focus({preventScroll:true});this._resize?.disconnect();clearTimeout(this._flashTimer);},
 methods:{
  trapFocus(e){const nodes=[...this.$refs.dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary')].filter(n=>n.offsetParent),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}},
  format(n){return Number(n||0).toLocaleString('fr-FR');},resource(k){return Number(this.state.resources[k]||0);},stock(k){return k==='money'?this.state.money:this.resource(k);},
  resourceName(k){return {money:'Pokédollars',crystal_shard:'Éclats fissurés',clear_crystal:'Cristaux limpides',aurora_prism:'Prismes d’aurore'}[k]||'Plaques '+catalog.types[k.replace('dark_plate_','').replace(/^./,s=>s.toUpperCase())];},
  radius(n){return {small:14,medium:20,large:27,giant:33,ultimate:48}[n.size];},glyph(n){return n.ultimate?'✧':n.branch==='combat'?'ϟ':n.branch==='capture'?'⌕':n.branch==='experience'?'↗':'₽';},
  available(n){if(this.state.nodes[n.id])return null;if(this.state.available<n.points)return 'Pas assez de points disponibles.';if(this.state.branches[n.branch]+n.points>31)return '31 points maximum dans une spécialisation.';if(n.ultimate&&this.state.branches[n.branch]!==30)return 'Investis d’abord 30 points dans cette spécialisation.';if(n.parents.some(id=>!this.state.nodes[id]))return 'Débloque les talents précédents sur ce chemin.';if(n.branch==='capture'&&n.size==='giant'&&catalog.nodes.some(other=>other.branch==='capture'&&other.size==='giant'&&this.state.nodes[other.id]))return 'Un seul talent géant de recherche à la fois.';return null;},
  sector(a){const p=angle=>`${1800+Math.cos(angle*Math.PI/180)*1720},${1800+Math.sin(angle*Math.PI/180)*1720}`;return `M1800,1800 L${p(a-45)} A1720,1720 0 0 1 ${p(a+45)} Z`;},
  measure(){const r=this.$refs.viewport?.getBoundingClientRect();if(r){const x=(this.width/2-this.offset.x)/this.zoom,y=(this.height/2-this.offset.y)/this.zoom;this.width=r.width;this.height=r.height;if(this._overview)this.overview();else this.offset={x:this.width/2-x*this.zoom,y:this.height/2-y*this.zoom};}},
  overview(){this._overview=true;this.zoom=Math.min(this.width,this.height)/3620;this.offset={x:this.width/2-1800*this.zoom,y:this.height/2-1800*this.zoom};},
  center(x,y,z){this._overview=false;this.zoom=z;this.offset={x:this.width/2-x*z,y:this.height/2-y*z};},
  focusBranch(key){this.branch=key;this.selectedId=null;this.refundConfirm=false;this.focusType();},
  focusType(){const nodes=catalog.nodes.filter(n=>n.branch===this.branch&&!n.ultimate&&(!n.type||n.type===this.type));const n=nodes.find(n=>!this.state.nodes[n.id])||nodes[0];if(n){this.selectNode(n);this.center(n.x,n.y,this.width<500?.85:.75);}},
  selectNode(n){if(!n||this._dragged)return;this.selectedId=n.id;this.branch=n.branch;if(n.type)this.type=n.type;this.choice=null;this.plates={};this.refundConfirm=false;},
  allocatePlates(){let remain=this.selected.mixedPlates;const p={};for(const type of Object.keys(catalog.types)){p[type]=Math.min(remain,this.resource('dark_plate_'+type.toLowerCase()));remain-=p[type];}this.plates=p;},
  command(action){const id=this.selectedId;this.$emit('command',action,{nodeId:id,revision:this.state.revision,...(action==='buy'&&this.selected.choices?{choice:this.choice}:{}),...(action==='buy'&&this.selected.mixedPlates&&!this.alreadyPaid?{plates:this.plates}:{})});this.flashId=id;clearTimeout(this._flashTimer);this._flashTimer=setTimeout(()=>{this.flashId=null;},900);},
  zoomAt(f,x,y){this._overview=false;const z=Math.max(.07,Math.min(2.5,this.zoom*f)),ratio=z/this.zoom;this.offset={x:x-(x-this.offset.x)*ratio,y:y-(y-this.offset.y)*ratio};this.zoom=z;},zoomBy(f){this.zoomAt(f,this.width/2,this.height/2);},wheel(e){const r=this.$refs.viewport.getBoundingClientRect();this.zoomAt(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},
  pointerDown(e){if(e.target.closest('button,.talent-summary'))return;if(e.isTrusted)this.$refs.viewport.setPointerCapture(e.pointerId);this._pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});this._dragged=false;this._travel=0;},
  pointerMove(e){const old=this._pointers.get(e.pointerId);if(!old)return;const before=[...this._pointers.values()];this._pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const after=[...this._pointers.values()];const dx=e.clientX-old.x,dy=e.clientY-old.y;this._travel+=Math.hypot(dx,dy);if(this._travel>5){this._dragged=true;this._overview=false;}if(before.length===2){const distance=p=>Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),r=this.$refs.viewport.getBoundingClientRect(),cx=(after[0].x+after[1].x)/2-r.left,cy=(after[0].y+after[1].y)/2-r.top;this.offset={x:this.offset.x+dx/2,y:this.offset.y+dy/2};if(distance(before)>0)this.zoomAt(distance(after)/distance(before),cx,cy);}else if(this._dragged)this.offset={x:this.offset.x+dx,y:this.offset.y+dy};},
  pointerUp(e){if(!this._dragged&&this._pointers.size===1){const element=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-talent-node]');if(element)this.selectNode(byId.get(element.getAttribute('data-talent-node')));}this._pointers.delete(e.pointerId);if(!this._pointers.size)setTimeout(()=>{this._dragged=false;},0);},pointerCancel(e){this._pointers.delete(e.pointerId);this._dragged=false;}
 }
};
</script>
<style scoped>
